using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class BeachFoodCarts{const string D="Assets/Scenes/Oasis/SouthBeach/FoodCarts",B="Assets/Scenes/Oasis/SouthBeach/BeachDetails";static BeachFoodCarts(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling)return;if(File.Exists("BeachFoodCartColors.request")){File.Delete("BeachFoodCartColors.request");Colors();return;}if(File.Exists("BeachFoodCartsRepair.request")){File.Delete("BeachFoodCartsRepair.request");Repair();return;}if(!File.Exists("BeachFoodCarts.request"))return;File.Delete("BeachFoodCarts.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/BeachFoodCarts.txt",e.ToString());Debug.LogException(e);}}
class G{public List<Vector3> p=new List<Vector3>();public List<Vector2> uv=new List<Vector2>();public List<Vector4> flags=new List<Vector4>();public List<Color> c=new List<Color>();public List<int> ids=new List<int>();public void Tri(Vector3 a,Vector3 b,Vector3 d,Color color,int tex=0,float glow=0){int k=p.Count;foreach(var v in new[]{a,b,d}){p.Add(v);c.Add(color);flags.Add(new Vector4(0,glow,tex==1?.8f:0,0));uv.Add(tex==1?new Vector2(.55f+v.x*.002f,.46f+v.y*.003f):new Vector2(.31f,.10f));}ids.AddRange(new[]{k,k+1,k+2});}public void Box(Vector3 q,Vector3 s,Color color,int tex=0,float glow=0){var v=new Vector3[8];for(int i=0;i<8;i++)v[i]=q+Vector3.Scale(new Vector3((i&1)==0?-.5f:.5f,(i&2)==0?-.5f:.5f,(i&4)==0?-.5f:.5f),s);foreach(var f in new[]{new[]{0,2,3,1},new[]{4,5,7,6},new[]{0,1,5,4},new[]{2,6,7,3},new[]{0,4,6,2},new[]{1,3,7,5}}){Tri(v[f[0]],v[f[1]],v[f[2]],color,tex,glow);Tri(v[f[0]],v[f[2]],v[f[3]],color,tex,glow);}}public void Pole(Vector3 a,Vector3 b,float r,Color color,int sides=8,int tex=0,float glow=0){var axis=(b-a).normalized;var u=Vector3.Cross(axis,Mathf.Abs(axis.y)>.9f?Vector3.forward:Vector3.up).normalized;var w=Vector3.Cross(axis,u);for(int k=0;k<sides;k++){float t=k*Mathf.PI*2/sides,z=(k+1)*Mathf.PI*2/sides;var x=r*(u*Mathf.Cos(t)+w*Mathf.Sin(t));var y=r*(u*Mathf.Cos(z)+w*Mathf.Sin(z));Tri(a+x,a+y,b+x,color,tex,glow);Tri(a+y,b+y,b+x,color,tex,glow);Tri(a,a+y,a+x,color,tex,glow);Tri(b,b+x,b+y,color,tex,glow);}}public Mesh Save(string n){var m=new Mesh{name=n};m.SetVertices(p);m.SetUVs(0,uv);m.SetUVs(1,flags);m.SetColors(c);m.SetTriangles(ids,0);m.RecalculateNormals();m.RecalculateTangents();m.RecalculateBounds();m.Optimize();AssetDatabase.CreateAsset(m,D+"/"+n+".asset");return m;}}
