static Color fascia=new Color(.025f,.032f,.04f);static G Make(bool far){var g=new G();g.Box(new Vector3(0,.79f,0),new Vector3(2.8f,1.05f,1.2f),steel,1);g.Box(new Vector3(0,.30f,0),new Vector3(2.88f,.11f,1.26f),steel,1);g.Box(new Vector3(0,1.36f,0),new Vector3(3.20f,.10f,1.40f),steel,1);g.Box(new Vector3(0,.83f,-.611f),new Vector3(2.36f,.74f,.025f),fascia);g.Box(new Vector3(0,2.91f,0),new Vector3(3.04f,.39f,1.35f),fascia);g.Box(new Vector3(0,2.69f,0),new Vector3(3.20f,.09f,1.46f),steel,1);
