foreach(float x in new[]{-1.24f,1.24f})g.Box(new Vector3(x,.83f,-.64f),new Vector3(.019f,.80f,.019f),warm,0,1.4f);
foreach(float y in new[]{1.78f,2.18f}){g.Box(new Vector3(0,y,0),new Vector3(2.59f,.025f,1.04f),glass);g.Box(new Vector3(0,y,-.54f),new Vector3(2.59f,.024f,.028f),steel,1);}
if(!far){foreach(float x in new[]{-1.76f,1.76f}){g.Box(new Vector3(x,1.36f,0),new Vector3(.65f,.05f,1.14f),steel,1);g.Pole(new Vector3(Mathf.Sign(x)*1.38f,.83f,0),new Vector3(x,1.32f,0),.026f,steel,6,1);}foreach(float x in new[]{-1.04f,-.5f,.5f,1.04f}){g.Box(new Vector3(x,2.64f,-.1f),new Vector3(.12f,.02f,.12f),warm,0,2);}
for(int k=0;k<3;k++){float x=-1.05f+k*.16f;g.Pole(new Vector3(x,1.42f,-.30f),new Vector3(x,1.68f,-.30f),.055f,k==0?new Color(.9f,.03f,.02f):new Color(1,.64f,.02f));g.Pole(new Vector3(x,1.68f,-.30f),new Vector3(x,1.76f,-.30f),.020f,warm,6);}
foreach(float x in new[]{-.82f,.82f}){g.Box(new Vector3(x,1.40f,.35f),new Vector3(.28f,.04f,.25f),black);g.Pole(new Vector3(x,1.44f,.35f),new Vector3(x,1.53f,.35f),.10f,new Color(.5f,.3f,.1f));}
foreach(float x in new[]{-1.02f,1.05f}){g.Pole(new Vector3(x,1.42f,.1f),new Vector3(x,1.58f,.1f),.09f,steel);for(int k=0;k<5;k++){float a=k*1.256f;g.Pole(new Vector3(x,1.56f,.1f),new Vector3(x+.12f*Mathf.Cos(a),1.77f,.1f+.12f*Mathf.Sin(a)),.035f,new Color(.16f,.42f,.07f),5);}}
foreach(float x in new[]{-.8f,0,.8f})g.Box(new Vector3(x,1.94f,.55f),new Vector3(.018f,1.14f,.018f),glass);
