}else{g.Box(new Vector3(0,2.89f,-.68f),new Vector3(.85f,.055f,.01f),warm);g.Box(new Vector3(0,.83f,-.64f),new Vector3(.56f,.025f,.01f),steel);}
return g;}
static void Letter(G g,string s,Vector3 q,float a,Color color){string[] rows={"111100110100100","111101101101111","110101101101110","110101110101110","111100110100111","010101111101101","111100100100111","101101111101101"};string alphabet="FODBEACH";float x=0;foreach(char ch in s){string bits=rows[alphabet.IndexOf(ch)];for(int y=0;y<5;y++)for(int k=0;k<3;k++)if(bits[y*3+k]=='1')g.Box(q+new Vector3(x+k*a,(4-y)*a,0),new Vector3(a*.83f,a*.83f,.006f),color);x+=4*a;}}
static Renderer Render(GameObject root,string name,Mesh m,Material mat){var g=new GameObject(name);g.transform.SetParent(root.transform,false);g.AddComponent<MeshFilter>().sharedMesh=m;var r=g.AddComponent<MeshRenderer>();r.sharedMaterial=mat;return r;}
static void Colors(){Repair();var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="15 Beach Food Carts");var names=new[]{"Ocean Blue","Coral Red","Palm Green","Golden Yellow"};var colors=new[]{new Color(.035f,.23f,.65f),new Color(.70f,.085f,.055f),new Color(.035f,.42f,.17f),new Color(.88f,.48f,.04f)};var mat=AssetDatabase.LoadAssetAtPath<Material>(B+"/Beach furniture existing atlas.mat");var prefabs=new GameObject[4];for(int i=0;i<4;i++){fascia=colors[i];var g=new GameObject(names[i]+" Beach Food Cart");var a=Render(g,"Detailed cart",Make(false).Save(names[i]+" cart near"),mat);var b=Render(g,"Distant cart",Make(true).Save(names[i]+" cart far"),mat);var lod=g.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.055f,new[]{a}),new LOD(.009f,new[]{b})});lod.RecalculateBounds();prefabs[i]=PrefabUtility.SaveAsPrefabAsset(g,D+"/"+names[i]+" Beach Food Cart.prefab");UnityEngine.Object.DestroyImmediate(g);}int k=0;foreach(var old in root.transform.Cast<Transform>().ToArray()){int index=k++%4;var g=(GameObject)PrefabUtility.InstantiatePrefab(prefabs[index],root.transform);g.name=old.name+" - "+names[index];g.transform.SetPositionAndRotation(old.position,old.rotation);g.transform.localScale=old.localScale;UnityEngine.Object.DestroyImmediate(old.gameObject);}PrefabUtility.SaveAsPrefabAssetAndConnect(root,D+"/15 Beach Food Carts.prefab",InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var cart=root.transform.GetChild(0);typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,cart.position-cart.forward*5+cart.right*4+Vector3.up*3,cart.position+Vector3.up*1.5f,"Beach-Food-Cart-Closeup"});File.AppendAllText("FinalEnvironmentRoadReview/BeachFoodCarts.txt","\nSUCCESS four interleaved fascia color variants: Ocean Blue 4, Coral Red 4, Palm Green 4, Golden Yellow 3. All 15 saved; same existing atlas/material and near/far LODs.\n");}
static void Repair(){foreach(bool distant in new[]{false,true}){var g=Make(distant);var m=AssetDatabase.LoadAssetAtPath<Mesh>(D+"/"+(distant?"Food cart distant silhouette":"Food cart detailed near")+".asset");m.Clear();m.indexFormat=UnityEngine.Rendering.IndexFormat.UInt16;m.SetVertices(g.p);m.SetUVs(0,g.uv);m.SetUVs(1,g.flags);m.SetColors(g.c);m.SetTriangles(g.ids,0);m.RecalculateNormals();m.RecalculateTangents();m.RecalculateBounds();m.Optimize();EditorUtility.SetDirty(m);}AssetDatabase.SaveAssets();var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="15 Beach Food Carts");if(root.transform.childCount!=15)throw new Exception("Cart count mismatch");var materials=root.GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Distinct().ToArray();if(materials.Length!=1||AssetDatabase.GetAssetPath(materials[0])!=B+"/Beach furniture existing atlas.mat")throw new Exception("Unexpected cart material");if(ShaderUtil.ShaderHasError(materials[0].shader))throw new Exception("Shader error");var cart=root.transform.GetChild(0);typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,cart.position-cart.forward*5+cart.right*4+Vector3.up*3,cart.position+Vector3.up*1.5f,"Beach-Food-Cart-Closeup"});File.AppendAllText("FinalEnvironmentRoadReview/BeachFoodCarts.txt","\nVERIFIED: 15 prefab instances; 2 LODs each; 1 reused material; unchanged Building02 texture; shader errors=0; steel UV/specular/upper trim corrected.\n");}
static void Run(){if(AssetDatabase.LoadAssetAtPath<GameObject>(D+"/15 Beach Food Carts.prefab"))throw new Exception("Food carts already exist; stop duplicate placement.");Directory.CreateDirectory(D);var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");if(!scene.isLoaded)throw new Exception("Expected scene not open");Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeFoodCarts");File.Copy(scene.path,"FinalEnvironmentRoadBackup/BeforeFoodCarts/Scene.unity",true);var mat=AssetDatabase.LoadAssetAtPath<Material>(B+"/Beach furniture existing atlas.mat");if(!mat||AssetDatabase.GetAssetPath(mat.GetTexture("_BaseMap"))!="Assets/Scenes/Oasis/3D/Texture/Building/Building-02.jpg")throw new Exception("Atlas/material verification failed");var near=Make(false).Save("Food cart detailed near");var far=Make(true).Save("Food cart distant silhouette");var prototype=new GameObject("Atlas Beach Food Cart");var n=Render(prototype,"Detailed stainless food cart",near,mat);var f=Render(prototype,"Distant food cart",far,mat);var lod=prototype.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.055f,new[]{n}),new LOD(.009f,new[]{f})});lod.RecalculateBounds();var prefab=PrefabUtility.SaveAsPrefabAsset(prototype,D+"/Atlas Beach Food Cart.prefab");UnityEngine.Object.DestroyImmediate(prototype);
var roads=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var cols=new List<MeshCollider>();var probes=new List<GameObject>();foreach(var mesh in roads.GetComponentsInChildren<MeshFilter>().Where(m=>m.name=="Outer_MEsh"||m.name=="Canal1")){var q=new GameObject("Food cart temporary beach probe");q.transform.position=mesh.transform.position;q.transform.rotation=mesh.transform.rotation;q.transform.localScale=mesh.transform.lossyScale;var co=q.AddComponent<MeshCollider>();co.sharedMesh=mesh.sharedMesh;cols.Add(co);probes.Add(q);}Physics.SyncTransforms();var yard=roads.GetComponentsInChildren<Renderer>().Single(r=>r.name=="Yatch_Port").bounds;yard.Expand(new Vector3(45,50,45));Func<Vector3,Vector3?> ground=q=>{if(yard.Contains(new Vector3(q.x,28,q.z)))return null;foreach(var co in cols){RaycastHit h;if(co.Raycast(new Ray(new Vector3(q.x,100,q.z),Vector3.down),out h,150)&&h.point.y>25.6f&&h.point.y<28.1f)return h.point;}return null;};var roots=scene.GetRootGameObjects().Where(g=>g.name=="South Coast Beach Details"||g.name=="Canal Bank Beach Details").ToArray();var obstacles=roots.SelectMany(g=>g.GetComponentsInChildren<LODGroup>()).Select(l=>l.transform.position).ToArray();var placed=new List<Vector3>();var root=new GameObject("15 Beach Food Carts");var report=new List<string>();foreach(var area in roots){int count=area.name.StartsWith("South")?7:8;var options=new List<Tuple<Vector3,Quaternion>>();foreach(var seat in area.GetComponentsInChildren<LODGroup>().Where(l=>l.name.Contains("Colorful"))){var outward=-seat.transform.forward;var tangent=seat.transform.right;foreach(float shift in new[]{-18f,-12f,-8f,8f,12f,18f})foreach(float inset in new[]{0f,2f,4f}){var pos=ground(seat.transform.position+tangent*shift-outward*inset);if(!pos.HasValue||obstacles.Any(p=>new Vector2(p.x-pos.Value.x,p.z-pos.Value.z).sqrMagnitude<25))continue;bool good=true;foreach(float dx in new[]{-1.8f,1.8f})foreach(float dz in new[]{-.8f,.8f}){var corner=ground(pos.Value+tangent*dx+outward*dz);if(!corner.HasValue||Mathf.Abs(corner.Value.y-pos.Value.y)>.17f)good=false;}if(good)options.Add(Tuple.Create(pos.Value,seat.transform.rotation));}}
for(int i=0;i<count;i++){if(options.Count==0)throw new Exception("Insufficient safe beach cart locations");var best=options.OrderByDescending(q=>placed.Count==0?q.Item1.z:placed.Min(p=>new Vector2(p.x-q.Item1.x,p.z-q.Item1.z).sqrMagnitude)).First();var obj=(GameObject)PrefabUtility.InstantiatePrefab(prefab,root.transform);obj.name="Beach Food Cart "+(placed.Count+1).ToString("00")+" - "+(count==7?"Outer Coast":"Canal Bank");obj.transform.position=best.Item1;obj.transform.rotation=best.Item2;placed.Add(best.Item1);options.RemoveAll(q=>Vector3.Distance(q.Item1,best.Item1)<55);report.Add(obj.name+" world="+obj.transform.position);}}
foreach(var probe in probes)UnityEngine.Object.DestroyImmediate(probe);PrefabUtility.SaveAsPrefabAssetAndConnect(root,D+"/15 Beach Food Carts.prefab",InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);report.Insert(0,"SUCCESS carts="+placed.Count+"; existing Building-02 atlas and existing furniture material only; no textures/materials added. Near triangles="+near.triangles.Length/3+" far="+far.triangles.Length/3+". Two LODs, instancing, no realtime lights/colliders. Footprint grounded; existing prop spacing >=5m; port excluded.");File.WriteAllLines("FinalEnvironmentRoadReview/BeachFoodCarts.txt",report);var first=placed[0];var cart=root.transform.GetChild(0);typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,first-cart.forward*5+cart.right*4+Vector3.up*3.0f,first+Vector3.up*1.5f,"Beach-Food-Cart-Closeup"});}
